import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { RATING_SCALE, notchChange, notchCalculator } from '../../src/ratings/notch.mjs';

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];

const INVALID = [
  '', '   ', 'BB B', 'Baa1', 'BBB−', 'BBB–', 'ＢＢＢ',
  'AAA+', 'CC', 'C', 'D', 'SD', 'RD', 'NR', 'WD',
  null, undefined, 7, {}, ['BBB'],
];

describe('RATING_SCALE (AC-1)', () => {
  test('deep-equals the 19 ratings in order', () => {
    assert.deepStrictEqual([...RATING_SCALE], EXPECTED_SCALE);
    assert.equal(RATING_SCALE.length, 19);
  });

  test('is frozen; push throws TypeError and length stays 19', () => {
    assert.equal(Object.isFrozen(RATING_SCALE), true);
    assert.throws(() => RATING_SCALE.push('CC'), TypeError);
    assert.equal(RATING_SCALE.length, 19);
  });
});

describe('notchChange', () => {
  test('downgrades are positive (AC-2)', () => {
    assert.equal(notchChange('BBB+', 'BBB'), 1);
    assert.equal(notchChange('BBB+', 'BBB-'), 2);
    assert.equal(notchChange('BBB+', 'BB+'), 3);
    assert.equal(notchChange('AAA', 'CCC-'), 18);
    assert.equal(notchChange('CCC', 'CCC-'), 1);
  });

  test('upgrades are negative (AC-3)', () => {
    assert.equal(notchChange('BB+', 'BBB+'), -3);
    assert.equal(notchChange('BBB', 'BBB+'), -1);
    assert.equal(notchChange('CCC-', 'AAA'), -18);
  });

  test('unchanged is +0, never -0 (AC-4)', () => {
    for (const r of RATING_SCALE) {
      const n = notchChange(r, r);
      assert.equal(n, 0);
      assert.ok(Object.is(n, 0), `${r}: expected +0`);
    }
  });

  test('trims and case-folds (AC-5)', () => {
    assert.equal(notchChange(' bbb+ ', 'BB+'), 3);
    assert.equal(notchChange('Bbb+', '\tbb+\n'), 3);
    assert.equal(notchChange(' aaa ', 'AAA'), 0);
    assert.equal(notchChange(' aaa ', 'AAA'), 0);
  });

  test('throws RangeError for invalid previous (AC-6)', () => {
    for (const bad of INVALID) {
      assert.throws(() => notchChange(bad, 'BBB'), RangeError, `previous=${String(bad)}`);
    }
  });

  test('throws RangeError for invalid current (AC-6)', () => {
    for (const bad of INVALID) {
      assert.throws(() => notchChange('BBB', bad), RangeError, `current=${String(bad)}`);
    }
  });

  test('throws RangeError when arguments are missing', () => {
    assert.throws(() => notchChange(), RangeError);
    assert.throws(() => notchChange('BBB'), RangeError);
  });

  test('error message names the argument and quotes the value', () => {
    assert.throws(() => notchChange('Baa1', 'BBB'), { message: 'Invalid rating for previous: "Baa1"' });
    assert.throws(() => notchChange('BBB', 'Baa1'), { message: 'Invalid rating for current: "Baa1"' });
  });

  test('returns a non-Promise value', () => {
    assert.equal(typeof notchChange('A', 'A'), 'number');
  });
});

describe('notchCalculator', () => {
  test('multi-notch downgrades (AC-7)', () => {
    assert.deepStrictEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
    assert.deepStrictEqual(notchCalculator('BBB+', 'BBB-'), { notches: 2, direction: 'downgrade', wl: 1 });
    assert.deepStrictEqual(notchCalculator('AAA', 'CCC-'), { notches: 18, direction: 'downgrade', wl: 2 });
  });

  test('one-notch downgrade gives wl 0 (AC-8)', () => {
    assert.deepStrictEqual(notchCalculator('BBB+', 'BBB'), { notches: 1, direction: 'downgrade', wl: 0 });
    assert.deepStrictEqual(notchCalculator('CCC', 'CCC-'), { notches: 1, direction: 'downgrade', wl: 0 });
  });

  test('upgrades and unchanged give wl 0 (AC-9)', () => {
    assert.deepStrictEqual(notchCalculator('BB+', 'BBB+'), { notches: -3, direction: 'upgrade', wl: 0 });
    assert.deepStrictEqual(notchCalculator('BBB', 'BBB+'), { notches: -1, direction: 'upgrade', wl: 0 });
    assert.deepStrictEqual(notchCalculator('CCC-', 'AAA'), { notches: -18, direction: 'upgrade', wl: 0 });
    const same = notchCalculator('A', 'A');
    assert.deepStrictEqual(same, { notches: 0, direction: 'unchanged', wl: 0 });
    assert.ok(Object.is(same.notches, 0));
  });

  test('normalises input (AC-5)', () => {
    assert.deepStrictEqual(notchCalculator('bbb+', 'bbb-'), { notches: 2, direction: 'downgrade', wl: 1 });
  });

  test('throws RangeError for invalid input in either position (AC-6)', () => {
    for (const bad of INVALID) {
      assert.throws(() => notchCalculator(bad, 'BBB'), RangeError, `previous=${String(bad)}`);
      assert.throws(() => notchCalculator('BBB', bad), RangeError, `current=${String(bad)}`);
    }
  });

  test('exhaustive over all 361 ordered pairs (AC-10)', () => {
    let count = 0;
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        count++;
        const r = notchCalculator(p, c);
        const n = notchChange(p, c);
        assert.deepStrictEqual(Object.keys(r).sort(), ['direction', 'notches', 'wl']);
        assert.equal(r.notches, n);
        assert.equal(r.direction, n > 0 ? 'downgrade' : n < 0 ? 'upgrade' : 'unchanged');
        assert.equal(r.wl, n <= 1 ? 0 : n === 2 ? 1 : 2);
        assert.ok([0, 1, 2].includes(r.wl));
        assert.notEqual(r, notchCalculator(p, c), 'each call returns a new object');
      }
    }
    assert.equal(count, 361);
  });
});

describe('module surface (AC-15)', () => {
  test('exports exactly RATING_SCALE, notchCalculator, notchChange; no default', async () => {
    const mod = await import('../../src/ratings/notch.mjs');
    assert.deepStrictEqual(Object.keys(mod).sort(), ['RATING_SCALE', 'notchCalculator', 'notchChange']);
    assert.equal('default' in mod, false);
  });
});
