// Rating scale and notch calculator (REQ-06-02). Pure and synchronous: no I/O.

export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]);

// Returns the scale index of a rating; throws RangeError for anything not on the scale.
function indexOf(value, argName) {
  if (typeof value === 'string') {
    const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
    if (index !== -1) return index;
  }
  throw new RangeError(`Invalid rating for ${argName}: ${describe(value)}`);
}

// Quotes the offending value for the error message without ever throwing.
function describe(value) {
  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    try {
      return String(value);
    } catch {
      return Object.prototype.toString.call(value);
    }
  }
}

// Positive = downgrade, negative = upgrade, unchanged = +0.
export function notchChange(previous, current) {
  const from = indexOf(previous, 'previous');
  const to = indexOf(current, 'current');
  return to - from;
}

// Indicator 13 thresholds: <=1 notch -> 0, 2 -> 1, >=3 -> 2; upgrades -> 0.
export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? 'downgrade' : notches < 0 ? 'upgrade' : 'unchanged';
  const wl = notches <= 1 ? 0 : notches === 2 ? 1 : 2;
  return { notches, direction, wl };
}
