// T-01 QA: integration tests for src/ratings/notch.mjs through its public exports only.
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import * as notch from '../../../src/ratings/notch.mjs';

const { RATING_SCALE, notchChange, notchCalculator } = notch;

const ROOT = fileURLToPath(new URL('../../../', import.meta.url));

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];

// Test data B (every argument position, both functions).
const INVALID = [
  ['empty string', ''],
  ['whitespace only', '   '],
  ['inner whitespace', 'BB B'],
  ['Baa1', 'Baa1'],
  ['U+2212 minus', 'BBB−'],
  ['AAA+', 'AAA+'],
  ['CC', 'CC'],
  ['C', 'C'],
  ['D', 'D'],
  ['SD', 'SD'],
  ['NR', 'NR'],
  ['null', null],
  ['undefined', undefined],
  ['number 7', 7],
  ['object {}', {}],
  ['array ["BBB"]', ['BBB']],
];

// Extra edge cases from the spec.
const INVALID_EXTRA = [
  ['en dash', 'BBB–'],
  ['fullwidth letters', 'ＢＢＢ'],
  ['RD', 'RD'],
  ['WD', 'WD'],
  ['inner tab', 'BB\tB'],
];

test('AC-1: RATING_SCALE is the frozen 19-step scale and push throws TypeError', () => {
  assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(Object.isFrozen(RATING_SCALE), true);
  assert.throws(() => RATING_SCALE.push('CC'), TypeError);
  assert.equal(RATING_SCALE.length, 19);
  assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
});

test('AC-1: RATING_SCALE cannot be mutated by assignment or sort in strict mode', () => {
  assert.throws(() => { RATING_SCALE[0] = 'X'; }, TypeError);
  assert.throws(() => RATING_SCALE.pop(), TypeError);
  assert.equal(RATING_SCALE[0], 'AAA');
});

test('AC-2: worse current gives a positive notch count', () => {
  assert.equal(notchChange('BBB+', 'BBB'), 1);
  assert.equal(notchChange('BBB+', 'BBB-'), 2);
  assert.equal(notchChange('BBB+', 'BB+'), 3);
  assert.equal(notchChange('AAA', 'CCC-'), 18);
  assert.equal(notchChange('CCC', 'CCC-'), 1);
});

test('AC-3: better current gives a negative notch count', () => {
  assert.equal(notchChange('BB+', 'BBB+'), -3);
  assert.equal(notchChange('BBB', 'BBB+'), -1);
  assert.equal(notchChange('CCC-', 'AAA'), -18);
});

test('AC-4: notchChange(r, r) is +0 (never -0) for all 19 ratings', () => {
  for (const r of EXPECTED_SCALE) {
    const result = notchChange(r, r);
    assert.equal(result, 0, r);
    assert.ok(Object.is(result, 0), `${r} must be +0, got ${Object.is(result, -0) ? '-0' : result}`);
  }
});

test('AC-5: notchChange accepts case and surrounding whitespace', () => {
  assert.equal(notchChange(' bbb+ ', 'BB+'), 3);
  assert.equal(notchChange('Bbb+', '\tbb+\n'), 3);
  assert.equal(notchChange(' aaa ', 'AAA'), 0);
  assert.ok(Object.is(notchChange(' aaa ', 'AAA'), 0));
});

test('AC-5: notchCalculator accepts case and surrounding whitespace', () => {
  assert.deepStrictEqual(notchCalculator('bbb+', 'bbb-'), { notches: 2, direction: 'downgrade', wl: 1 });
  assert.deepStrictEqual(notchCalculator(' \tbbb+\n', ' BB+ '), { notches: 3, direction: 'downgrade', wl: 2 });
});

test('AC-6: notchChange throws RangeError for every invalid value as previous', () => {
  for (const [label, bad] of [...INVALID, ...INVALID_EXTRA]) {
    assert.throws(() => notchChange(bad, 'BBB'), (e) => e instanceof RangeError && !(e instanceof TypeError), `previous=${label}`);
  }
